(() => {
  const button = document.getElementById('downloadProposal');

  button.addEventListener('click', () => {
    const details = window.proposalData;
    if (!details?.packageId) {
      alert('Complete and save the Managed IT & Cybersecurity Support section before downloading the proposal.');
      return;
    }
    // The proposal .docx is generated by the backend pricing service and is
    // not available in this embedded (static) version of the calculator.
    alert('Your estimate is ready on screen. To receive the formatted proposal document, please use the "Copy estimate" button and share it with the Neozaar team.');
  });
})();
